args.content:
/* Antigravity UI — __PARAM__component */
/* Design language: weightless, floating, glassmorphism */

.ag-__PARAM__component {
  /* Float above the surface */
  transform: translateY(-2px);
  transition: transform 0.3s ease, box-shadow 0.3s ease;

  /* Glassmorphism base */
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);

  /* Soft ethereal border */
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;

  /* Weightless shadow — lifts upward */
  box-shadow:
    0 -2px 10px rgba(255, 255, 255, 0.03),
    0 8px 32px rgba(0, 0, 0, 0.2);

  /* Breathing room */
  padding: 1.5rem;
}

.ag-__PARAM__component:hover {
  /* Elevate further on hover */
  transform: translateY(-6px);
  box-shadow:
    0 -4px 20px rgba(255, 255, 255, 0.05),
    0 16px 48px rgba(0, 0, 0, 0.3);
}

/* Inner glow for depth */
.ag-__PARAM__component::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    ellipse at top center,
    rgba(255, 255, 255, 0.06) 0%,
    transparent 60%
  );
  pointer-events: none;
  z-index: -1;
}

/* Light theme override */
@media (prefers-color-scheme: light) {
  .ag-__PARAM__component {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(0, 0, 0, 0.06);
    box-shadow:
      0 -2px 10px rgba(255, 255, 255, 0.5),
      0 8px 32px rgba(0, 0, 0, 0.08);
  }
}
